"""Frozen SQLite v1 fixture from commit c186631, before stage 3 second-half migration."""
SCHEMA_V1 = 'CREATE TABLE runs(run_id TEXT PRIMARY KEY,started_utc TEXT NOT NULL,monotonic_start REAL NOT NULL,mode TEXT NOT NULL,output_dir TEXT NOT NULL,ended_utc TEXT,exit_code INTEGER,signal INTEGER,complete INTEGER,submitted INTEGER,dropped_full INTEGER,rejected INTEGER,committed INTEGER,commits INTEGER,last_rx_id INTEGER);CREATE TABLE frames(run_id TEXT NOT NULL REFERENCES runs(run_id),rx_id INTEGER NOT NULL,session INTEGER NOT NULL,utc TEXT NOT NULL,elapsed_s REAL NOT NULL,raw_start INTEGER NOT NULL,raw_end INTEGER NOT NULL,body BLOB NOT NULL,v INTEGER NOT NULL,reason TEXT NOT NULL,flags INTEGER NOT NULL,gap INTEGER NOT NULL,coal INTEGER NOT NULL,snap INTEGER NOT NULL,n INTEGER NOT NULL,sequence_relation TEXT NOT NULL,PRIMARY KEY(run_id,rx_id));CREATE TABLE points(run_id TEXT NOT NULL,rx_id INTEGER NOT NULL,point_index INTEGER NOT NULL,src TEXT NOT NULL,id TEXT NOT NULL,value INTEGER NOT NULL,scale INTEGER NOT NULL,unit TEXT NOT NULL,quality TEXT NOT NULL,status TEXT NOT NULL,value_ms INTEGER NOT NULL,status_ms INTEGER NOT NULL,seq INTEGER NOT NULL,value_kind TEXT NOT NULL,is_current INTEGER NOT NULL,PRIMARY KEY(run_id,rx_id,point_index),FOREIGN KEY(run_id,rx_id) REFERENCES frames(run_id,rx_id));PRAGMA application_id=1196897073;PRAGMA user_version=1;'
